import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.jit
def swizzle_tile(
    tile_id,
    M,
    N,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
    GROUP_SIZE_M: tl.constexpr,
):
    grid_m = tl.cdiv(M, BLOCK_M)
    grid_n = tl.cdiv(N, BLOCK_N)
    width = GROUP_SIZE_M * grid_n
    group_id = tile_id // width
    group_size = tl.minimum(GROUP_SIZE_M, grid_m - group_id * GROUP_SIZE_M)
    pid_m = group_id * GROUP_SIZE_M + (tile_id % group_size)
    pid_n = (tile_id % width) // group_size
    return pid_m, pid_n


def _configs():
    return [
        triton.Config(
            {"BLOCK_M": 128, "BLOCK_N": 128, "BLOCK_K": 32, "GROUP_SIZE_M": 4},
            num_warps=16,
            num_stages=2,
        ),
    ]


@triton.autotune(configs=_configs(), key=["M", "N", "K"])
@triton.jit
def _matmul_kernel(
    a_ptr,
    b_ptr,
    c_ptr,
    M,
    N,
    K,
    stride_am,
    stride_ak: tl.constexpr,
    stride_bk,
    stride_bn: tl.constexpr,
    stride_cm,
    stride_cn: tl.constexpr,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
    BLOCK_K: tl.constexpr,
    GROUP_SIZE_M: tl.constexpr,
):
    pid = tl.program_id(0)
    pid_m, pid_n = swizzle_tile(pid, M, N, BLOCK_M, BLOCK_N, GROUP_SIZE_M)

    a_desc = tl.make_tensor_descriptor(
        base=a_ptr,
        shape=(M, K),
        strides=(stride_am, stride_ak),
        block_shape=(BLOCK_M, BLOCK_K),
    )
    b_desc = tl.make_tensor_descriptor(
        base=b_ptr,
        shape=(K, N),
        strides=(stride_bk, stride_bn),
        block_shape=(BLOCK_K, BLOCK_N),
    )

    off_m = pid_m * BLOCK_M
    off_n = pid_n * BLOCK_N
    acc = tl.zeros((BLOCK_M, BLOCK_N), dtype=tl.float32)

    for off_k in range(0, K, BLOCK_K):
        a_tile = a_desc.load([off_m, off_k])
        b_tile = b_desc.load([off_k, off_n])
        acc += tl.dot(a_tile, b_tile)
    c_desc = tl.make_tensor_descriptor(
        base=c_ptr,
        shape=(M, N),
        strides=(stride_cm, stride_cn),
        block_shape=(BLOCK_M, BLOCK_N),
    )
    c_desc.store([off_m, off_n], acc.to(c_ptr.type.element_ty))


class Model(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A, B):
        device = A.device
        A = A.contiguous()
        B = B.contiguous()

        M_out, K = A.shape
        N_out = B.shape[1]

        C = torch.empty((M_out, N_out), device=device, dtype=A.dtype)

        grid = lambda META: (
            triton.cdiv(M_out, META["BLOCK_M"]) * triton.cdiv(N_out, META["BLOCK_N"]),
        )

        _matmul_kernel[grid](
            A,
            B,
            C,
            M_out,
            N_out,
            K,
            A.stride(0),
            A.stride(1),
            B.stride(0),
            B.stride(1),
            C.stride(0),
            C.stride(1),
        )
        return C


